import hashlib
import hmac
import os
import threading
from collections import deque
from typing import Optional, Tuple, Union


class CryptoContext:
    """Represents a cryptographic context with key material."""

    def __init__(self, key: bytes, algorithm: str = "sha256"):
        self._key = key
        self._algorithm = algorithm
        self._nonce_counter = 0
        self._lock = threading.Lock()

    @property
    def key(self) -> bytes:
        return self._key

    @property
    def algorithm(self) -> str:
        return self._algorithm

    def derive_session_key(self, salt: bytes) -> bytes:
        """Derive a session-specific key using HKDF-like construction."""
        with self._lock:
            self._nonce_counter += 1
            nonce = self._nonce_counter.to_bytes(8, 'big')
        prk = hmac.new(self._key, salt + nonce, self._algorithm).digest()
        return hmac.new(prk, b"session-key" + nonce, self._algorithm).digest()

    def compute_mac(self, data: bytes) -> bytes:
        """Compute MAC over data using the context key."""
        return hmac.new(self._key, data, self._algorithm).digest()


class ConnectionState:
    """Tracks per-connection cryptographic state."""

    def __init__(self, conn_id: str, crypto_ctx: CryptoContext):
        self.conn_id = conn_id
        self.crypto_ctx = crypto_ctx
        self.is_authenticated = False
        self.message_counter = 0
        self._verified_peers: list = []

    def authenticate(self, peer_mac: bytes, challenge: bytes) -> bool:
        """Verify peer authentication using MAC comparison."""
        expected = self.crypto_ctx.compute_mac(challenge)
        if hmac.compare_digest(expected, peer_mac):
            self.is_authenticated = True
            return True
        return False

    def record_verified_peer(self, peer_id: Union[str, bytes]):
        """Record a verified peer identifier."""
        self._verified_peers.append(peer_id)

    def get_peer_count(self) -> int:
        return len(self._verified_peers)


class SecureConnectionPool:
    """Thread-safe connection pool with cryptographic session management."""

    def __init__(self, master_key: bytes, pool_size: int = 10):
        self._master_key = master_key
        self._pool_size = pool_size
        self._available: deque = deque()
        self._in_use: dict = {}
        self._lock = threading.RLock()
        self._connection_registry: dict = {}
        self._init_pool()

    def _init_pool(self):
        """Initialize the connection pool with crypto contexts."""
        for i in range(self._pool_size):
            conn_id = f"conn-{i:04d}"
            salt = os.urandom(16)
            ctx = CryptoContext(self._master_key, "sha256")
            state = ConnectionState(conn_id, ctx)
            self._available.append(state)
            self._connection_registry[conn_id] = state

    def acquire(self, requester_id: str) -> Optional[ConnectionState]:
        """Acquire a connection from the pool."""
        with self._lock:
            if not self._available:
                return None
            state = self._available.popleft()
            self._in_use[requester_id] = state
            return state

    def release(self, requester_id: str):
        """Release a connection back to the pool."""
        with self._lock:
            if requester_id in self._in_use:
                state = self._in_use.pop(requester_id)
                state.is_authenticated = False
                state.message_counter = 0
                self._available.append(state)

    def verify_and_dispatch(self, requester_id: str, payload: bytes, 
                            auth_token: Union[bytes, str]) -> Tuple[bool, bytes]:
        """Verify authentication token and dispatch secure message.

        The auth_token can be provided as bytes (raw MAC) or as a 
        hex-encoded string for API compatibility.
        """
        conn = self._in_use.get(requester_id)
        if conn is None:
            return (False, b"no active connection")

        # Normalize auth_token to bytes
        token_bytes = self._normalize_token(auth_token)

        # Compute expected MAC
        expected_mac = conn.crypto_ctx.compute_mac(payload)

        # Verify using constant-time comparison
        if hmac.compare_digest(token_bytes, expected_mac):
            conn.message_counter += 1
            response = self._process_secure_payload(conn, payload)
            return (True, response)

        return (False, b"authentication failed")

    def _normalize_token(self, token: Union[bytes, str]) -> bytes:
        """Normalize token to bytes for comparison.

        Accepts both raw bytes and hex-encoded strings.
        Uses isinstance for proper subclass handling.
        """
        if isinstance(token, bytes):
            return token
        if isinstance(token, str):
            try:
                return bytes.fromhex(token)
            except ValueError:
                return token.encode('utf-8')
        # Reject any other type - strict type checking
        raise TypeError(f"auth_token must be bytes or str, got {type(token).__name__}")

    def _process_secure_payload(self, conn: ConnectionState, 
                                payload: bytes) -> bytes:
        """Process an authenticated payload."""
        session_key = conn.crypto_ctx.derive_session_key(
            conn.conn_id.encode() + conn.message_counter.to_bytes(4, 'big')
        )
        response_mac = hmac.new(session_key, payload, "sha256").digest()
        return response_mac


def create_pool(secret: str, size: int = 10,
                salt: Optional[bytes] = None) -> SecureConnectionPool:
    """Factory function to create a properly initialized pool.

    Derives the master key from the secret using PBKDF2-HMAC-SHA256 with a
    salt and a high iteration count instead of a single unsalted hash, to
    resist brute-force/dictionary attacks against the secret.
    """
    if salt is None:
        # A stable salt derived from a fixed application context; for
        # per-deployment security a randomly generated salt should be
        # persisted and passed in explicitly.
        salt = hashlib.sha256(b"SecureConnectionPool/kdf-salt/v1").digest()
    key = hashlib.pbkdf2_hmac("sha256", secret.encode(), salt, 200_000, dklen=32)
    return SecureConnectionPool(key, size)


# Application entry point
if __name__ == "__main__":
    pool = create_pool("application-secret-key-2024", size=5)

    # Simulate connection lifecycle
    conn = pool.acquire("client-1")
    if conn:
        challenge = os.urandom(32)
        mac = conn.crypto_ctx.compute_mac(challenge)
        assert conn.authenticate(mac, challenge)

        # Dispatch a message
        message = b"transfer funds to account 12345"
        auth = conn.crypto_ctx.compute_mac(message)
        success, response = pool.verify_and_dispatch("client-1", message, auth)
        assert success

        pool.release("client-1")
